import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as n,o as r,j as i,G as o,ae as a,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"PREVENTING WOKE AI IN THE FEDERAL GOVERNMENT","description":"","frontmatter":{"legisId":"2025-07-23-preventing-woke-ai-in-the-federal-government","title":"PREVENTING WOKE AI IN THE FEDERAL GOVERNMENT","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/07/preventing-woke-ai-in-the-federal-government/","publishDate":"2025-07-23T18:47:48-04:00"},"headers":[],"relativePath":"executive-orders/2025-07-23-preventing-woke-ai-in-the-federal-government.md","filePath":"executive-orders/2025-07-23-preventing-woke-ai-in-the-federal-government.md"}'),l={name:"executive-orders/2025-07-23-preventing-woke-ai-in-the-federal-government.md"},h=Object.assign(l,{setup(d){return(c,e)=>(r(),n("div",null,[e[0]||(e[0]=i("h1",{id:"preventing-woke-ai-in-the-federal-government",tabindex:"-1"},[s("PREVENTING WOKE AI IN THE FEDERAL GOVERNMENT "),i("a",{class:"header-anchor",href:"#preventing-woke-ai-in-the-federal-government","aria-label":'Permalink to "PREVENTING WOKE AI IN THE FEDERAL GOVERNMENT"'},"​")],-1)),o(t),e[1]||(e[1]=a('<p>Published on Wednesday, July 23, 2025</p><ul><li><p><strong>Purpose of Executive Order</strong>: Establishes principles for procuring trustworthy artificial intelligence (AI) models within federal agencies.</p></li><li><p><strong>Critical Role of AI</strong>: Highlights AI&#39;s importance in learning, information consumption, and daily navigation for Americans, emphasizing the need for reliable outputs.</p></li><li><p><strong>Concerns About Ideological Biases</strong>:</p><ul><li>Identifies &quot;diversity, equity, and inclusion&quot; (DEI) as a significant ideological threat to AI accuracy.</li><li>Warns against distortions in AI outputs related to race, sex, and factual representation due to DEI biases.</li></ul></li><li><p><strong>Unbiased AI Principles</strong>:</p><ol><li><strong>Truth-seeking</strong>: AI models must produce accurate, objective responses and acknowledge uncertainty when data is incomplete.</li><li><strong>Ideological Neutrality</strong>: AI models should be impartial, avoiding manipulation towards ideological ends unless requested by users.</li></ol></li><li><p><strong>Implementation Requirements</strong>:</p><ul><li>Within 120 days, the Director of the Office of Management and Budget (OMB) must issue guidance for agencies on compliance with AI principles.</li><li>Agencies are required to: <ul><li>Include Unbiased AI Principles in new contracts for AI models.</li><li>Aim to revise existing contracts accordingly.</li><li>Establish procedures to ensure compliance with standards.</li></ul></li></ul></li><li><p><strong>Consultation and Flexibility</strong>: The OMB guidance will consider technical limitations, allow vendor transparency about ideological judgments, avoid over-prescription, and make exceptions for national security contexts.</p></li><li><p><strong>Legal Authority and Regulatory Framework</strong>:</p><ul><li>The order does not affect the existing legal authority of departments or agencies.</li><li>It stipulates no new rights or legal benefits for individuals or entities against the U.S. government.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/07/preventing-woke-ai-in-the-federal-government/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/07/preventing-woke-ai-in-the-federal-government/</a></p>',3))]))}});export{p as __pageData,h as default};
